const campaigns = [salescloser];
const now = new Date();
const live = (c) => c.active && (!c.start || new Date(c.start + 'T00:00:00') <= now) && (!c.end || now <= new Date(c.end + 'T23:59:59'));
const has = (c, p) => !c.placements || c.placements.includes(p);
